/* HEXA BATTLEGROUNDS setup — PART 4 OF 4. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-grid-602', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | J I H T R\n2 | P V F M T\n3 | E G R O U\n4 | D G L Y Z\n5 | I J V W C","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 3)  (3, 4)  (2, 1)  (1, 4)  (1, 3)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["GLIDE"]}]'::jsonb, false, 3, 150, 'The code is a 5-letter word ending in E.', 'Reading (column,row) gives GLIDE; reading it as (row,column) gives nonsense (FOPTH).', null, 25, 'published'), ('airdrop-grid-603', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | D L S H M\n2 | M A G S L\n3 | X H N N A\n4 | P P L O I\n5 | Y N X V Y","mono":true},"decoder":{"title":"Marked coordinates","body":"(4, 2)  (5, 4)  (3, 2)  (4, 3)  (5, 3)  (2, 1)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SIGNAL"]}]'::jsonb, false, 3, 150, 'The code is a 6-letter word ending in L.', 'Reading (column,row) gives SIGNAL; reading it as (row,column) gives nonsense (PVHLXM).', null, 25, 'published'), ('airdrop-grid-604', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | L L H W J\n2 | T B Y P R\n3 | P Z R A X\n4 | K H U A H\n5 | A A S C X","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 5)  (3, 4)  (4, 2)  (1, 3)  (2, 1)  (3, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SUPPLY"]}]'::jsonb, false, 3, 150, 'The code is a 6-letter word ending in Y.', 'Reading (column,row) gives SUPPLY; reading it as (row,column) gives nonsense (XAHHTZ).', null, 25, 'published'), ('airdrop-grid-605', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | L D C R B\n2 | A D N D J\n3 | I A V M N\n4 | X S A O R\n5 | H L A O J","mono":true},"decoder":{"title":"Marked coordinates","body":"(4, 1)  (3, 5)  (2, 1)  (3, 4)  (5, 4)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["RADAR"]}]'::jsonb, false, 3, 150, 'The code is a 5-letter word ending in R.', 'Reading (column,row) gives RADAR; reading it as (row,column) gives nonsense (XNAMO).', null, 25, 'published'), ('airdrop-grid-606', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | U W B D T\n2 | K Y L N J\n3 | C H F E R\n4 | A G Y Y T\n5 | R S I O B","mono":true},"decoder":{"title":"Marked coordinates","body":"(5, 4)  (1, 4)  (5, 3)  (2, 4)  (4, 3)  (5, 1)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["TARGET"]}]'::jsonb, false, 3, 150, 'The code is a 6-letter word ending in T.', 'Reading (column,row) gives TARGET; reading it as (row,column) gives nonsense (ODINYR).', null, 25, 'published'), ('airdrop-grid-607', 'grid', 'airdrop', 'Airdrop Lock', 'observation', 2, array['any']::text[], 'The airdrop crate is locked with a grid code. First squad to crack it takes the loot.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5\n1 | N H W N I\n2 | D N J E X\n3 | G J C P Z\n4 | G H I M L\n5 | M M A S S","mono":true},"decoder":{"title":"Marked coordinates","body":"(1, 3)  (5, 4)  (5, 1)  (1, 2)  (4, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["GLIDE"]}]'::jsonb, false, 3, 150, 'The code is a 5-letter word ending in E.', 'Reading (column,row) gives GLIDE; reading it as (row,column) gives nonsense (WSMHH).', null, 25, 'published'), ('finale_entry-caesar-700', 'caesar', 'finale_entry', 'Signal Intercept', 'decoding', 2, array['finale']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 104.9 MHz ]  UMTJSNC\n[ 91.1 MHz ]  FORWOBH\n[ 107.2 MHz ]  XVEBILX","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 104.9 MHz\nEncryption key: 5\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["PHOENIX"]}]'::jsonb, false, 4, 180, 'The answer has 7 letters and starts with P.', '104.9 MHz carries UMTJSNC; shifting back by 5 gives PHOENIX.', null, 25, 'published'), ('finale_entry-caesar-701', 'caesar', 'finale_entry', 'Signal Intercept', 'decoding', 2, array['finale']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 101.3 MHz ]  TKHARG\n[ 98.7 MHz ]  VGORGUV\n[ 107.2 MHz ]  IKCCYJ","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 98.7 MHz\nEncryption key: 2\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["TEMPEST"]}]'::jsonb, false, 4, 180, 'The answer has 7 letters and starts with T.', '98.7 MHz carries VGORGUV; shifting back by 2 gives TEMPEST.', null, 25, 'published'), ('finale_entry-caesar-702', 'caesar', 'finale_entry', 'Signal Intercept', 'decoding', 2, array['finale']::text[], 'Squad 00 is broadcasting on several frequencies. Decode the genuine transmission and enter the plain word.', '{"scout":{"title":"Intercepted signals","body":"[ 104.9 MHz ]  CPEJQT\n[ 91.1 MHz ]  ASZPYTI\n[ 94.3 MHz ]  IKCCYJ","mono":true},"decoder":{"title":"Cipher manual","body":"Every letter was pushed FORWARD along the alphabet by the key number.\nTo decode, move each letter BACKWARD by the key.\nWrap around: A moved back 1 becomes Z."},"intel":{"title":"Verified intel","body":"Genuine frequency: 104.9 MHz\nEncryption key: 2\nAll other frequencies are decoys."}}'::jsonb, '[{"label":"Decoded word","accept":["ANCHOR"]}]'::jsonb, false, 4, 180, 'The answer has 6 letters and starts with A.', '104.9 MHz carries CPEJQT; shifting back by 2 gives ANCHOR.', null, 25, 'published'), ('finale_exchange-triad-800', 'relay', 'finale_exchange', 'Intelligence Exchange', 'tech', 1, array['finale']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"Which port does plain HTTP use by default?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"How many bytes are in one kibibyte (KiB)?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["80"]},{"label":"Part 2 (Decoder)","accept":["1024"]},{"label":"Part 3 (Intel)","accept":["404"]}]'::jsonb, true, 4, 240, 'The three numbers have 2, 4, 3 digits.', 'Which port does plain HTTP use by default? → 80 | How many bytes are in one kibibyte (KiB)? → 1024 | HTTP status code for "Not Found"? → 404', null, 25, 'published'), ('finale_exchange-triad-801', 'relay', 'finale_exchange', 'Intelligence Exchange', 'tech', 1, array['finale']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"HTTP status code for \"OK\"?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"How many bits are in one byte?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"How many layers does the OSI model have?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["200"]},{"label":"Part 2 (Decoder)","accept":["8"]},{"label":"Part 3 (Intel)","accept":["7"]}]'::jsonb, true, 4, 240, 'The three numbers have 3, 1, 1 digits.', 'HTTP status code for "OK"? → 200 | How many bits are in one byte? → 8 | How many layers does the OSI model have? → 7', null, 25, 'published'), ('finale_exchange-triad-802', 'relay', 'finale_exchange', 'Intelligence Exchange', 'tech', 1, array['finale']::text[], 'Another squad''s captain holds your access codeword. Get it through captain comms, then add the three-part tech code from your own squad. If no one helps, your Intel Officer receives a backup copy later (half reward).', '{"scout":{"title":"Code fragment 1 of 3","body":"How many bits are in one byte?\n\nTell your captain the number. It is part 1 of the code."},"decoder":{"title":"Code fragment 2 of 3","body":"HTTP status code for \"Not Found\"?\n\nTell your captain the number. It is part 2 of the code."},"intel":{"title":"Code fragment 3 of 3","body":"Binary 1111 equals which decimal number?\n\nTell your captain the number. It is part 3 of the code."}}'::jsonb, '[{"label":"Partner codeword","accept":["KEY"]},{"label":"Part 1 (Scout)","accept":["8"]},{"label":"Part 2 (Decoder)","accept":["404"]},{"label":"Part 3 (Intel)","accept":["15"]}]'::jsonb, true, 4, 240, 'The three numbers have 1, 3, 2 digits.', 'How many bits are in one byte? → 8 | HTTP status code for "Not Found"? → 404 | Binary 1111 equals which decimal number? → 15', null, 25, 'published'), ('finale_battle-orders-coffee-900', 'orders', 'finale_battle', 'Barista Rush', 'memory', 1, array['finale']::text[], 'Squad 00 swapped the bills. Calculate the correct total for the order your intel points to and enter the number.', '{"scout":{"title":"Order slips on the counter","body":"Table 3: 3× Croissant, 3× Cookie\nTable 6: 2× Croissant, 1× Cookie, 1× Latte\nTable 5: 1× Latte, 2× Croissant, 2× Cold Brew\nTable 9: 2× Latte, 3× Croissant","mono":true},"decoder":{"title":"Costa counter price card","body":"Latte — 12\nMocha — 14\nCappuccino — 11\nEspresso — 8\nMuffin — 9\nCookie — 5\nCroissant — 10\nCold Brew — 13","mono":true},"intel":{"title":"Billing intel","body":"Bill Table 6.\nCorrection: the Cookie quantity on that slip was written as half. Double it."}}'::jsonb, '[{"label":"Total","accept":["42"]}]'::jsonb, false, 3, 150, 'Multiply each quantity by its price, add them, then apply the house rule.', 'Table 6 with the rule applied totals 42.', null, 25, 'published'), ('finale_battle-orders-food-901', 'orders', 'finale_battle', 'Mess Hall Ledger', 'memory', 1, array['finale']::text[], 'Squad 00 swapped the bills. Calculate the correct total for the order your intel points to and enter the number.', '{"scout":{"title":"Order slips on the counter","body":"Table 2: 2× Dosa, 1× Idli\nTable 7: 1× Meals, 3× Curd Rice\nTable 3: 2× Dosa, 1× Juice\nTable 12: 2× Dosa, 3× Meals","mono":true},"decoder":{"title":"Canteen price board","body":"Biryani — 18\nDosa — 10\nIdli — 6\nMeals — 15\nPaneer Roll — 12\nJuice — 7\nCurd Rice — 9\nVada — 5","mono":true},"intel":{"title":"Billing intel","body":"Bill Table 12.\nHouse rule today: add 5 coins for takeaway packing (once per order)."}}'::jsonb, '[{"label":"Total","accept":["70"]}]'::jsonb, false, 3, 150, 'Multiply each quantity by its price, add them, then apply the house rule.', 'Table 12 with the rule applied totals 70.', null, 25, 'published'), ('finale_battle-orders-coffee-902', 'orders', 'finale_battle', 'Barista Rush', 'memory', 1, array['finale']::text[], 'Squad 00 swapped the bills. Calculate the correct total for the order your intel points to and enter the number.', '{"scout":{"title":"Order slips on the counter","body":"Table 6: 3× Latte, 1× Mocha, 3× Muffin\nTable 5: 3× Cappuccino, 1× Croissant\nTable 3: 3× Espresso, 2× Latte, 2× Cookie\nTable 11: 2× Muffin, 2× Croissant, 2× Latte","mono":true},"decoder":{"title":"Costa counter price card","body":"Latte — 12\nMocha — 14\nCappuccino — 11\nEspresso — 8\nMuffin — 9\nCookie — 5\nCroissant — 10\nCold Brew — 13","mono":true},"intel":{"title":"Billing intel","body":"Bill Table 11.\nHouse rule today: every Muffin is free."}}'::jsonb, '[{"label":"Total","accept":["44"]}]'::jsonb, false, 3, 150, 'Multiply each quantity by its price, add them, then apply the house rule.', 'Table 11 with the rule applied totals 44.', null, 25, 'published'), ('finale_battle-sequence-900', 'sequence', 'finale_battle', 'Pattern Lock', 'logic', 2, array['finale']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  2, 3, 5, 8, 13, ?\nBRAVO:  1, 4, 9, 16, 25, ?\nCHARLIE:  2, 4, 8, 16, 32, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number minus 1."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["35"]}]'::jsonb, false, 3, 150, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 36; converted: 35.', null, 25, 'published'), ('finale_battle-sequence-901', 'sequence', 'finale_battle', 'Pattern Lock', 'logic', 2, array['finale']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  6, 13, 20, 27, 34, ?\nBRAVO:  4, 9, 16, 25, 36, ?\nCHARLIE:  1, 3, 4, 7, 11, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number plus 10."},"intel":{"title":"Insider tip","body":"The genuine pattern is BRAVO. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["59"]}]'::jsonb, false, 3, 150, 'Look at the difference (or ratio) between neighbouring numbers.', 'BRAVO continues with 49; converted: 59.', null, 25, 'published'), ('finale_battle-sequence-902', 'sequence', 'finale_battle', 'Pattern Lock', 'logic', 2, array['finale']::text[], 'Only one of the patterns on the lock is real. Find its missing number and convert it into the unlock code.', '{"scout":{"title":"Lock display","body":"ALPHA:  3, 7, 15, 31, 63, ?\nBRAVO:  3, 4, 7, 11, 18, ?\nCHARLIE:  3, 6, 12, 24, 48, ?","mono":true},"decoder":{"title":"Unlock conversion","body":"Submit the missing number minus 1."},"intel":{"title":"Insider tip","body":"The genuine pattern is ALPHA. The other two are decoys."}}'::jsonb, '[{"label":"Unlock code","accept":["126"]}]'::jsonb, false, 3, 150, 'Look at the difference (or ratio) between neighbouring numbers.', 'ALPHA continues with 127; converted: 126.', null, 25, 'published'), ('finale_battle-binary-900', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag D:  ○ ○ ● ○ ○\nTag B:  ● ○ ● ○ ●\nTag G:  ○ ● ● ○ ○\nTag F:  ○ ● ● ● ●\nTag J:  ○ ○ ○ ● ●","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nJ → G → F → B → D"}}'::jsonb, '[{"label":"Badge word","accept":["CLOUD"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'J=3=C, G=12=L, F=15=O, B=21=U, D=4=D → CLOUD.', null, 25, 'published'), ('finale_battle-binary-901', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag G:  ● ○ ○ ● ●\nTag R:  ○ ○ ○ ● ●\nTag N:  ○ ● ○ ● ●\nTag K:  ○ ○ ○ ○ ●\nTag B:  ● ○ ● ○ ○","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nG → B → K → R → N"}}'::jsonb, '[{"label":"Badge word","accept":["STACK"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'G=19=S, B=20=T, K=1=A, R=3=C, N=11=K → STACK.', null, 25, 'published'), ('finale_battle-binary-902', 'binary', 'finale_battle', 'Badge Reader', 'tech', 2, array['finale']::text[], 'A stolen access badge flashed its lights. Rebuild the word it encodes.', '{"scout":{"title":"Badge light capture","body":"Tag R:  ○ ○ ● ○ ●\nTag H:  ● ○ ○ ● ○\nTag J:  ○ ● ● ○ ●\nTag W:  ○ ○ ● ○ ●\nTag K:  ○ ○ ● ● ●","mono":true},"decoder":{"title":"Reader protocol","body":"● = 1 and ○ = 0. Each row is a 5-bit binary number.\nBit values from left to right: 16 8 4 2 1.\nThe number is the letter''s position in the alphabet (1 = A, 2 = B … 26 = Z)."},"intel":{"title":"Read order","body":"Read the tags in this order:\nJ → R → H → K → W"}}'::jsonb, '[{"label":"Badge word","accept":["MERGE"]}]'::jsonb, false, 3, 150, 'It is a 5-letter tech word.', 'J=13=M, R=5=E, H=18=R, K=7=G, W=5=E → MERGE.', null, 25, 'published'), ('final_code-grid-1000', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | D J U R L F\n2 | E Z N E B S\n3 | V V E A S R\n4 | O O I F Z E\n5 | D S N X C R\n6 | I N W B I G","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 5)  (3, 4)  (6, 3)  (3, 1)  (6, 2)  (6, 4)  (6, 5)  (1, 6)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["SIRUSERI"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in I.', 'Reading (column,row) gives SIRUSERI; reading it as (row,column) gives nonsense (BAWVNBIF).', null, 25, 'published'), ('final_code-grid-1001', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | Z J Z T N O\n2 | H G W R Y M\n3 | N F B Y A F\n4 | O M B Q E X\n5 | K U L F J O\n6 | R P Q L H V","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 1)  (5, 4)  (4, 2)  (1, 4)  (1, 2)  (6, 5)  (2, 5)  (1, 6)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["ZEROHOUR"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in R.', 'Reading (column,row) gives ZEROHOUR; reading it as (row,column) gives nonsense (NFMTJHYO).', null, 25, 'published'), ('final_code-grid-1002', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | W P N F C J\n2 | V D N U A Z\n3 | G C E F A H\n4 | O P A Y R Z\n5 | U N M X Z X\n6 | J C I U H I","mono":true},"decoder":{"title":"Marked coordinates","body":"(2, 6)  (5, 6)  (3, 4)  (3, 5)  (2, 4)  (3, 6)  (1, 4)  (3, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["CHAMPION"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in N.', 'Reading (column,row) gives CHAMPION; reading it as (row,column) gives nonsense (ZXFAUHFC).', null, 25, 'published'), ('final_code-grid-1003', 'grid', 'final_code', 'The Final Code', 'observation', 2, array['finale']::text[], 'Squad 00''s master vault. Read the final code from the grid. This is worth the most points of the night.', '{"scout":{"title":"Aerial grid photo","body":"    1 2 3 4 5 6\n1 | Y S O O M K\n2 | L I E E G Z\n3 | A O K S O H\n4 | L F P S E C\n5 | X W X C L E\n6 | A W H I R S","mono":true},"decoder":{"title":"Marked coordinates","body":"(3, 6)  (5, 4)  (1, 5)  (1, 6)  (2, 6)  (1, 3)  (5, 6)  (3, 2)"},"intel":{"title":"Grid convention","body":"Each pair is (COLUMN, ROW).\nColumns run left → right, rows run top → bottom, both starting at 1.\nRead the marked letters in the order listed."}}'::jsonb, '[{"label":"Drop code","accept":["HEXAWARE"]}]'::jsonb, false, 4, 240, 'The code is a 8-letter word ending in E.', 'Reading (column,row) gives HEXAWARE; reading it as (row,column) gives nonsense (HCMKZOEO).', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
